#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Threading;
namespace FileCompass {
 internal static class DispatchUnitsTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow main=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();var settings=new ProgramSettings{TextEditorPath=Path.Combine(Environment.SystemDirectory,"notepad.exe")};
   foreach(string ext in new[]{".xls",".xlsx",".xlsb",".xlsm",".doc",".docx",".dotx",".ppt",".pptx",".ppsx",".pdf",".zip",".7z",".accdb",".dwg",".psd",".svgz"}){string file=Path.Combine(root,"Example"+ext);check(!FileViewers.CanEditInternally(file)&&FileViewers.UsesAssociatedEditor(file),"Non-text type goes directly to its external application: "+ext);var info=FileViewers.AssociatedOpenInfo(file,(e,n,verb)=>n==1?"registered handler":null);check(info.UseShellExecute&&info.Verb=="open"&&info.FileName==file,"Default Open is used even when Edit is also registered: "+ext);}
   foreach(string extension in new[]{".patch",".diff",".unfamiliar"}){string textFile=Path.Combine(root,"Source"+extension);File.WriteAllText(textFile,"diff --git a/file b/file\n+Příliš žluťoučký kůň\n",new System.Text.UTF8Encoding(false));check(FileViewers.CanEditInternally(textFile),"structured/unknown text can open internally: "+extension);check(EditorTextFile.Load(textFile).Text.Contains("žluťoučký"),"text content and encoding are retained: "+extension);}foreach(byte[] bytes in new[]{new byte[]{0,1,2,3},new byte[]{1,2,3,4,5}}){string binary=Path.Combine(root,"Binary.unfamiliar");File.WriteAllBytes(binary,bytes);check(!FileViewers.CanEditInternally(binary),"unknown binary content is not routed to the internal editor");}
   string unassociated=Path.Combine(root,"Unassociated.xls");File.WriteAllText(unassociated,"fixture");var missing=FileViewers.AssociatedOpenInfo(unassociated,(e,n,v)=>null);check(missing.Verb=="openas","Missing association requests the Windows application chooser");string chosen=null;int launches=0;FileViewers.OpenWithForTests=file=>chosen=file;FileViewers.StartAssociatedEdit(missing,info=>launches++);check(chosen==unassociated&&launches==0,"Unassociated XLS shows the chooser without attempting a broken launch");foreach(int error in new[]{1155,31,2,3}){chosen=null;FileViewers.StartAssociatedEdit(new ProcessStartInfo(unassociated){UseShellExecute=true,Verb="open"},info=>{throw new System.ComponentModel.Win32Exception(error);});check(chosen==unassociated,"Broken association falls back to the chooser: "+error);}FileViewers.OpenWithForTests=null;
   foreach(string ext in new[]{".cs",".json",".yaml",".txt",".csv",".svg",".py",".ps1"})check(FileViewers.CanEditInternally("Example"+ext),"Text/source type remains editable internally: "+ext);
   foreach(string ext in new[]{".exe",".lnk",".cmd",".js",".ps1"}){var info=FileViewers.LaunchInfo(Path.Combine(root,"Example"+ext),settings,true);check(info.FileName==settings.TextEditorPath&&!String.IsNullOrEmpty(info.Arguments),"Editing executable content passes it as data to an editor: "+ext);}
   foreach(string ext in new[]{".html",".htm",".HTML"}){string html=Path.Combine(root,"Example with spaces"+ext);var open=FileViewers.ExternalEditorInfo(html,settings);check(open.FileName==Path.Combine(Environment.SystemDirectory,"notepad.exe")&&open.Arguments==SshTerminal.QuoteWindowsArgument(html),"HTML external edit explicitly uses Notepad: "+ext);check(FileViewers.LaunchInfo(html,settings,true).FileName==open.FileName,"Legacy external edit also keeps HTML out of a browser");}string excelStub=Path.Combine(root,"EXCEL.EXE");File.WriteAllBytes(excelStub,new byte[0]);string csv=Path.Combine(root,"Example with spaces.csv");var csvOpen=FileViewers.ExcelEditInfo(csv,()=>excelStub);check(csvOpen.FileName==excelStub&&csvOpen.Arguments==SshTerminal.QuoteWindowsArgument(csv),"CSV is passed directly to Excel as a quoted filename");bool noExcel=false;try{FileViewers.ExcelEditInfo(csv,()=>null);}catch(IOException){noExcel=true;}check(noExcel,"Missing Excel reports an error instead of opening the wrong application");check(FileViewers.CanEditInternally(csv)&&FileViewers.CanEditInternally("Example.html"),"Plain F4 can still edit CSV and HTML internally");
   string sample=Path.Combine(root,"Example.txt");File.WriteAllText(sample,"example");main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);var panel=AdvancedToolsTests.Visual<FilePanel>(main).First();typeof(MainWindow).GetMethod("SetActive",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(main,new object[]{panel});panel.List.SelectedItem=panel.List.Items.Cast<Entry>().Single(x=>x.FullPath==sample);ProcessStartInfo launched=null;FileViewers.AssociatedStartForTests=info=>launched=info;check(main.HandleExternalEditorShortcut(Key.F4,ModifierKeys.Shift)&&launched!=null,"Shift+F4 dispatches straight to the external application");check(!Application.Current.Windows.OfType<CodeEditorWindow>().Any(),"Shift+F4 never opens the internal editor");check(!main.HandleExternalEditorShortcut(Key.F4,ModifierKeys.None),"Plain F4 remains a separate command");var external=panel.List.ContextMenu.Items.OfType<MenuItem>().Single(x=>Convert.ToString(x.Tag)=="codeEditor.external");check(external.InputGestureText=="Shift+F4","File context menu displays Shift+F4");check(!AdvancedToolsTests.Visual<Button>(main).Any(x=>Convert.ToString(x.ToolTip).Contains("Shift+F4")),"External editor icon is absent from the toolbar");
   var dialog=new CopyProgressDialog(main,new CopyControl());dialog.Update(new CopyUpdate{Phase=L.Code("copy.title"),BytesPerSecond=104857600,TotalBytes=1048576000,FileTotal=1048576000});dialog.Show();dialog.UpdateLayout();check(AdvancedToolsTests.Visual<TextBlock>(dialog).Any(x=>x.Text.Contains("100")&&x.Text.Contains("MiB/s")),"104857600 bytes/s is displayed as 100 MiB/s");check(Math.Abs(114400.0/1024-111.7)<.1,"TC screenshot values match binary rather than decimal scaling");dialog.Close();main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL: "+ex+Environment.NewLine+String.Join(Environment.NewLine,checks));return 1;}finally{FileViewers.OpenWithForTests=null;FileViewers.AssociatedStartForTests=null;if(main!=null)main.Close();}}
 }
}
#endif
